pub fn score_bin(item_size: u32, bin_residual: u32, post_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Penalize if multiple bins are open and no fitting items are available
    if open_bins_count > 1 && fitting_bins_count == 0 {
        score -= 0.9;
    }

    // Reward for reducing residual difference from mean residual
    let residual_diff = (mean_residual - post_residual).abs();
    if residual_diff < mean_residual / 2.0 {
        score += (mean_residual - post_residual) * 0.6;
    } else if residual_diff < mean_residual {
        score += (mean_residual - post_residual) * 0.4;
    }

    // Penalize very low and moderate residuals
    if post_residual < 3 { score -= 1.5; }
    else if post_residual < 8 { score -= 1.0; }

    // Reward for item size close to bin capacity within a tolerance
    let tolerance = mean_residual / 2.0;
    if item_size <= bin_capacity - mean_residual + tolerance && item_size >= bin_capacity - mean_residual - tolerance {
        score += 0.8;
    } else if item_size <= bin_capacity - mean_residual && item_size >= bin_capacity - mean_residual * 1.5 {
        score += 0.6;
    }

    // Penalize next item size exceeding bin capacity
    let next_item_penalty = if next_item_size > bin_capacity { 1.4 } else { 0.0 };

    // Penalize if fitting bins are limited and next item fits poorly
    let fitting_bins_penalty = if next_item_size > post_residual && fitting_bins_count == 1 { 0.7 } else { 0.0 };

    score -= (next_item_penalty + fitting_bins_penalty) * 3.5;

    // Reward for low residual with available fitting bins
    if post_residual <= 10 && fitting_bins_count > 0 {
        score += 0.5;
    }

    // Penalize if a significant number of open bins is present
    if open_bins_count > total_items / 3 { score -= 0.2 * open_bins_count as f64; }

    // Adjust final score based on post-residual and bin capacity ratio
    score = (score * 0.75 + ((post_residual as f64) / bin_capacity as f64) * 0.25);

    score
}

