pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize bins with small post_residual to avoid creating unusable dead space
    if post_residual < 10 {
        score += (10 - post_residual) * 5.0; // Higher penalty for smaller gaps
    }

    // Favor bins with fewer open bins remaining
    score -= open_bins_count as f64 * 2.0;

    // Penalize if there are no fitting bins left
    if fitting_bins_count == 0 {
        score += bin_capacity as f64; // Large penalty if no space in any open bin
    }

    // Apply a lookahead factor based on the next item size
    if next_item_size > bin_residual {
        score -= (next_item_size - bin_residual) as f64 * 3.0; // Penalize if next item won't fit in current bin
    } else if next_item_size < bin_residual / 2 {
        score += ((bin_residual / 2) - next_item_size) as f64 * 1.5; // Reward if next item fits well in current bin
    }

    // Adjust score based on the mean residual to balance compaction
    score -= (mean_residual * open_bins_count as f64) * 0.5;

    score
}

