        score -= 1.5;
    } else if post_residual < 10 {
        score -= 0.5;
    }

    // Reward items that are close to fitting exactly into a bin
    if item_size <= bin_capacity - mean_residual && item_size >= bin_capacity - mean_residual * 2 {
        score += 0.4;
    } else if item_size <= bin_capacity - (mean_residual / 2.0) && item_size >= bin_capacity - (mean_residual / 2.0) * 2 {
        score += 0.15;
    }

    // Penalize if the next item is too large for the current or next open bin
