        score -= 2.0;
    } else if next_item_size > bin_capacity / 2.0 || (next_item_size > post_residual / 2.0 && fitting_bins_count == 1) {
        score -= 1.0;
    }

    // Reward bins that are almost full but can still fit one more item
    if post_residual <= 30 && fitting_bins_count > 0 {
        score += 0.5;
    } else if post_residual <= 20 {
        score += 0.2;
    }

